const items = $input.all();
if (!items || items.length === 0) return [{ json: { emails: [], contactMap: {} } }];

const contacts = items.map(i => i.json);
const contactMap = {};
const emailList = [];

for (const c of contacts) {
  if (c.email) {
    const emailLower = c.email.toLowerCase().trim();
    contactMap[emailLower] = { id: c.id, company_name: c.company_name };
    emailList.push(emailLower);
  }
}

if (emailList.length === 0) return [{ json: { emails: [], contactMap: {} } }];

// Gmail search: replies from any of these senders in last 60 days
const fromQuery = emailList.map(e => `from:${e}`).join(' OR ');
const searchQuery = `(${fromQuery}) in:inbox newer_than:60d`;

return [{ json: { searchQuery, contactMap, totalContacts: emailList.length } }];

// Match each Gmail message to a contact by sender email
const messages = $input.all();
const contactMap = $('Build Search Query').first().json.contactMap;

const matches = [];

for (const msg of messages) {
  const headers = msg.json.payload?.headers || [];
  const fromHeader = headers.find(h => h.name?.toLowerCase() === 'from');
  if (!fromHeader) continue;

  // Extract email from 'From: Name <email@domain.com>' or 'email@domain.com'
  const fromRaw = fromHeader.value || '';
  const emailMatch = fromRaw.match(/<([^>]+)>/) || fromRaw.match(/([\w.+-]+@[\w.-]+\.[a-z]{2,})/i);
  if (!emailMatch) continue;

  const senderEmail = emailMatch[1].toLowerCase().trim();
  const contact = contactMap[senderEmail];
  if (!contact) continue;

  // Get snippet (first 200 chars of reply content)
  const snippet = (msg.json.snippet || '').substring(0, 200);

  matches.push({
    contact_id: contact.id,
    company_name: contact.company_name,
    sender_email: senderEmail,
    reply_snippet: snippet,
    gmail_thread_id: msg.json.threadId
  });
}

// Deduplicate by contact_id (take first reply per contact)
const seen = new Set();
const unique = matches.filter(m => {
  if (seen.has(m.contact_id)) return false;
  seen.add(m.contact_id);
  return true;
});

if (unique.length === 0) return [{ json: { matched: 0 } }];
return unique.map(m => ({ json: m }));
